  def tokenize(value: Long): Token = numericTokenizer.tokenize(value)

  def tokenize(value: Double): Token = numericTokenizer.tokenize(value)

  def tokenize(value: Float): Token = numericTokenizer.tokenize(value)

  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)

  def tokenize(value: LocalDateTime): Token = temporalTokenizer.tokenize(value)

  def tokenize(value: LocalDate): Token = temporalTokenizer.tokenize(value)

  def tokenize(value: Tokenizable): Token =
    Token(value.toToken, TokenType.STRUCTURED)

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => tokenize(t)
    case s: String => tokenize(s)
    case bytes: Array[Byte] => tokenize(bytes)
    case n: Int => tokenize(n)
    case n: Long => tokenize(n)
    case n: Double => tokenize(n)
    case n: Float => tokenize(n)
    case n: BigDecimal => tokenize(n)
    case n: BigInt => Token(n.toString, TokenType.NUMERIC, Map("original_type" -> "BigInt"))
    case dt: LocalDateTime => tokenize(dt)
    case d: LocalDate => tokenize(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

final class TokenRegistry[T] {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit =
    registry.update(key, container)

  def addHandler(handler: T => Option[Token]): Unit =
    handlers += handler

  def process(key: String): List[Option[Token]] = {
    registry
      .get(key)
      .map { container =>
        container.getAll.toList.map { item =>
          handlers.iterator
            .map(handler => handler(item))
            .collectFirst { case Some(token) => token }
        }
      }
      .getOrElse(List.empty)
  }
}

// ============================================================================
// Higher-Kinded Type Simulation
// ============================================================================

class TokenFunctor[+A](protected val value: A) {
  def map[B](func: A => B): TokenFunctor[B] = new TokenFunctor(func(value))

  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] = func(value)

  def getOrElse[B >: A](default: => B): B = Option(value).getOrElse(default)

  def get: A = value
}

final class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get(value))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  private val printer: Printer = if (pretty) Printer.spaces2 else Printer.noSpaces

  def tokenize(value: Json): Token = {
    val jsonStr = printer.print(value)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenize(value: Any): Token = tokenize(toJson(value))

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    var current: Json = value

    for (part <- parts) {
      val next =
        current.asObject.flatMap(_.apply(part))
          .orElse {
            if (part.forall(_.isDigit)) {
              val idx = part.toInt
              current.asArray.flatMap(_.lift(idx))
            } else {
              None
            }
          }

      next match {
        case Some(json) => current = json
        case None => return None
      }
    }

    Some(tokenize(current))
  }

  def tokenizePath(value: Any, path: String): Option[Token] =
    tokenizePath(toJson(value), path)

  private def toJson(value: Any): Json = value match {
    case null => Json.Null
    case json: Json => json
    case s: String => Json.fromString(s)
    case b: Boolean => Json.fromBoolean(b)
    case i: Int => Json.fromInt(i)
    case l: Long => Json.fromLong(l)
    case d: Double => Json.fromDoubleOrNull(d)
    case f: Float => Json.fromFloatOrNull(f)
    case bd: BigDecimal => Json.fromBigDecimal(bd.bigDecimal)
    case bi: BigInt => Json.fromBigInt(bi.bigInteger)
    case seq: Seq[_] => Json.fromValues(seq.map(toJson))
    case arr: Array[_] => Json.fromValues(arr.toSeq.map(toJson))
    case map: Map[_, _] =>
      val fields = map.collect {
        case (k: String, v) => (k, toJson(v))
      }
      Json.fromFields(fields)
    case other => Json.fromString(other.toString)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripPunct(word) else word
    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) {
      None
    } else {
      val truncated = maxLength match {
        case Some(limit) if normalized.length > limit => normalized.take(limit)
        case _ => normalized
      }
      if (truncated.isEmpty) None else Some(truncated)
    }
  }

  private def stripPunct(word: String): String = {
    val leadingStripped = word.dropWhile(punctuation.contains)
    leadingStripped.reverse.dropWhile(punctuation.contains).reverse
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    val tokens = mutable.ListBuffer.empty[Token]

    for ((word, idx) <- words.zipWithIndex) {
      processToken(word).foreach { processed =>
        tokens += Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> idx, "original" -> word)
        )
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val safeStart = if (start >= 0) start else currentPos
      val end = safeStart + word.length

      processToken(word).foreach { processed =>
        result += ((processed, safeStart, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers = mutable.ListBuffer.empty[String => String]
  private val validators = mutable.ListBuffer.empty[T => Boolean]
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ entries
    this
  }

  def build(): T => Token = {
    val normalizersSnapshot = normalizers.toList
    val validatorsSnapshot = validators.toList
    val metadataSnapshot = metadata

    (value: T) => {
      validatorsSnapshot.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      val normalized = normalizersSnapshot.foldLeft(value.toString) { (acc, norm) =>
        norm(acc)
      }

      Token(normalized, TokenType.STRING, metadataSnapshot)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
